select sources.id,scholarships.id,records.source_record_key,scholarships.canonical_url,jsonb_build_object('fact_source','official university scholarship portal','verified_on','2026-08-20'),now(),now() from records join scholarships using(canonical_url) join sources on sources.name=scholarships.sponsor||' Scholarship Portal'
